func rgb(_ r: CGFloat, _ g: CGFloat, _ b: CGFloat) -> CGColor {
    CGColor(red: r / 255, green: g / 255, blue: b / 255, alpha: 1)
}

struct Sheet {
    let c: CGContext

    func page(_ content: () -> Void) {
        c.beginPDFPage(nil)
        c.saveGState()
        c.translateBy(x: 0, y: 792)
        c.scaleBy(x: 1, y: -1)
        content()
        c.restoreGState()
        c.endPDFPage()
    }

    func rect(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat, _ fill: CGColor, _ radius: CGFloat = 0) {
        c.setFillColor(fill)
        c.addPath(CGPath(roundedRect: CGRect(x: x, y: y, width: w, height: h), cornerWidth: radius, cornerHeight: radius, transform: nil))
        c.fillPath()
    }

    func ellipse(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat, _ fill: CGColor) {
        c.setFillColor(fill)
        c.fillEllipse(in: CGRect(x: x, y: y, width: w, height: h))
    }

    func line(_ points: [(CGFloat, CGFloat)], _ color: CGColor, _ width: CGFloat = 1) {
        c.setStrokeColor(color)
        c.setLineWidth(width)
        c.setLineCap(.round)
        c.setLineJoin(.round)
        c.beginPath()
        c.move(to: CGPoint(x: points[0].0, y: points[0].1))
        for (x, y) in points.dropFirst() { c.addLine(to: CGPoint(x: x, y: y)) }
        c.strokePath()
    }

    func polygon(_ points: [(CGFloat, CGFloat)], _ fill: CGColor) {
        c.setFillColor(fill)
        c.beginPath()
        c.move(to: CGPoint(x: points[0].0, y: points[0].1))
        for (x, y) in points.dropFirst() { c.addLine(to: CGPoint(x: x, y: y)) }
        c.closePath()
        c.fillPath()
    }

    func text(_ value: String, _ x: CGFloat, _ baseline: CGFloat, _ font: String, _ size: CGFloat,
              _ color: CGColor, width: CGFloat, tracking: CGFloat = 0, right: Bool = false) {
        let attr = NSAttributedString(string: value, attributes: [
            NSAttributedString.Key(kCTFontAttributeName as String): CTFontCreateWithName(font as CFString, size, nil),
            NSAttributedString.Key(kCTForegroundColorAttributeName as String): color,
            NSAttributedString.Key(kCTKernAttributeName as String): tracking
        ])
        let line = CTLineCreateWithAttributedString(attr)
        let length = CTLineGetTypographicBounds(line, nil, nil, nil)
        precondition(length <= width, \"Too wide (\\(length) > \\(width)): \\(value)\")
        c.saveGState()
        c.textMatrix = .identity
        c.translateBy(x: right ? x - length : x, y: baseline)
        c.scaleBy(x: 1, y: -1)
        c.textPosition = .zero
        CTLineDraw(line, c)
        c.restoreGState()
    }

    func lines(_ values: [String], _ x: CGFloat, _ baseline: CGFloat, _ font: String, _ size: CGFloat,
               _ leading: CGFloat, _ color: CGColor, width: CGFloat) {
        for (index, value) in values.enumerated() {
            text(value, x, baseline + CGFloat(index) * leading, font, size, color, width: width)
        }
    }

    func overline(_ value: String, _ x: CGFloat, _ baseline: CGFloat, _ color: CGColor = muted, width: CGFloat = 440) {
        text(value, x, baseline, strong, 10.5, color, width: width, tracking: 1.5)
    }

    func trim(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat) {
        for (cx, dx) in [(x, -1.0), (x + w, 1.0)] {
            for (cy, dy) in [(y, -1.0), (y + h, 1.0)] {
                line([(cx + dx * 3, cy), (cx + dx * 10, cy)], muted, 0.48)
                line([(cx, cy + dy * 3), (cx, cy + dy * 10)], muted, 0.48)
            }
        }
    }

    func card(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat, _ fill: CGColor, _ content: () -> Void) {
        trim(x, y, w, h)
        c.saveGState()
        c.translateBy(x: x, y: y)
        rect(0, 0, w, h, fill)
        content()
        c.restoreGState()
    }
}

func pdf(_ filename: String, _ title: String, _ draw: (Sheet) -> Void) {
    var bounds = CGRect(x: 0, y: 0, width: 612, height: 792)
    let options = [kCGPDFContextTitle: title] as CFDictionary
    let context = CGContext(output.appendingPathComponent(filename) as CFURL, mediaBox: &bounds, options)"'!
    draw(Sheet(c: context))
    context.closePDF()
}

